const raw = $input.first().json;
const message = raw.messages?.[0];
if (!message?.from) return [];
const text = message.type === 'text' && message.text?.body?.trim() ? message.text.body.trim() : '';
const output = !text ? 'Please send your trip details as text for now.' : text.length > 4000 ? 'Please shorten your message to 4000 characters or less.' : /^\s*(hi|hello|hey)\s*[!.]?\s*$/i.test(text) ? "Hi, I'm Glide. I can help plan a vacation, business trip, or everyday journey. Where are you thinking of going?" : /\b(book|buy|purchase|pay|cancel|change|reschedule|modify)\b/i.test(text) ? "I can help prepare that, but live booking and payment connections are not active yet, so I can't complete purchases, cancellations, or reservation changes. Share the trip dates and any reservation reference, and I'll organize the next step. Before a future action, I'll show the exact option, total price, fees, and terms for your approval." : '';
return [{ json: { text, sessionId: 'wa:' + message.from, channel: 'whatsapp', recipient: message.from, phoneNumberId: raw.metadata?.phone_number_id || '', messageId: message.id || '', ...(output ? { output } : {}) } }];

